<script setup>
import {ref,computed,watch,onBeforeUnmount} from 'vue';
import {api,action} from '../lib/api.js';
import {completedTasks,taskTime,shortPrompt} from '../lib/experienceRuns.js';
import TaskEvidence from './TaskEvidence.vue';
import BaseDialog from './BaseDialog.vue';
const props=defineProps({work:Object,view:{type:String,default:'all'},allSessions:Boolean});
const rows=ref([]),jobs=ref([]),selected=ref(''),confirmed=ref(false),submitting=ref(false),sourceDetails=ref({}),sourceBusy=ref(''),extractError=ref(''),deleteConfirm=ref(''),deleting=ref(''),focus=ref(''),query=ref(''),enabledFilter=ref('all'),detailId=ref('');
const busy=computed(()=>submitting.value||jobs.value.some(job=>['queued','running'].includes(job.status)));
const runs=computed(()=>completedTasks(props.work.s.events));
const detailRow=computed(()=>rows.value.find(row=>row.id===detailId.value)||null);
function openDetail(row){detailId.value=row.id;deleteConfirm.value='';}
const visibleJobs=computed(()=>props.view==='summary'?jobs.value.filter(job=>job.status!=='completed'):jobs.value);
const filteredRows=computed(()=>{const term=query.value.trim().toLowerCase();return rows.value.filter(row=>(enabledFilter.value==='all'||row.enabled===(enabledFilter.value==='enabled'))&&(!term||[row.title,row.when,row.strategy].some(text=>String(text||'').toLowerCase().includes(term))));});
const selectedTask=computed(()=>runs.value.find(run=>run.id===selected.value));
const sessionScope=computed(()=>selected.value==='__session__'||(!selected.value&&!!focus.value.trim()));
const canExtract=computed(()=>sessionScope.value?runs.value.some(run=>run.successTools>0):selectedTask.value?.successTools>0);
const jobLabels={queued:'等待总结',running:'后台总结中',completed:'总结完成',failed:'总结失败',interrupted:'总结已中断'};
let timer,disposed=false,revision=0;
function poll(){clearTimeout(timer);if(!disposed&&jobs.value.some(job=>['queued','running'].includes(job.status)))timer=setTimeout(()=>props.work.safe(refresh),2000);}
watch(selected,()=>{confirmed.value=false;extractError.value='';});
async function refresh(){
  const id=props.work.s.session,request=++revision;if(!id){rows.value=[];jobs.value=[];return;}
  try{const data=await api(props.allSessions?'/api/experiences':`/api/sessions/${id}/experiences`);
    if(!disposed&&id===props.work.s.session&&request===revision){rows.value=data.experiences;jobs.value=data.jobs||[];
      if(!selected.value){const active=jobs.value.find(job=>['queued','running'].includes(job.status));if(active){selected.value=active.source_scope==='session'?'__session__':active.run_id;focus.value=active.focus||'';}}}
  }finally{if(!disposed&&id===props.work.s.session&&request===revision)poll();}
}
watch(()=>props.work.s.session,()=>{revision++;clearTimeout(timer);rows.value=[];jobs.value=[];selected.value='';confirmed.value=false;sourceDetails.value={};extractError.value='';deleteConfirm.value='';detailId.value='';focus.value='';props.work.safe(refresh);},{immediate:true});
onBeforeUnmount(()=>{disposed=true;revision++;clearTimeout(timer);});
async function extract(){
  const id=props.work.s.session,run=selected.value;if(!id||busy.value||!canExtract.value||!confirmed.value)return;
  submitting.value=true;extractError.value='';
  try{const data=await action(`/api/sessions/${id}/experiences/jobs`,{run_id:sessionScope.value?'':run,confirmed:true,focus:focus.value.trim(),source_scope:sessionScope.value?'session':'run'});
    if(!disposed&&id===props.work.s.session){revision++;if(data.job)jobs.value=[data.job,...jobs.value.filter(job=>job.id!==data.job.id)];confirmed.value=false;poll();await refresh();}
  }catch(error){if(!disposed&&id===props.work.s.session)extractError.value=error.message;}
  finally{submitting.value=false;}
}
async function toggle(row){const id=props.work.s.session;await api(props.allSessions?`/api/experiences/${row.id}`:`/api/sessions/${id}/experiences/${row.id}`,{method:'PATCH',body:JSON.stringify({enabled:!row.enabled})});if(!disposed&&id===props.work.s.session)await refresh();}
async function remove(row){const id=props.work.s.session;if(deleting.value)return;deleting.value=row.id;
  try{await api(props.allSessions?`/api/experiences/${row.id}`:`/api/sessions/${id}/experiences/${row.id}`,{method:'DELETE'});if(!disposed&&id===props.work.s.session){if(detailId.value===row.id)detailId.value='';rows.value=rows.value.filter(item=>item.id!==row.id);delete sourceDetails.value[row.id];deleteConfirm.value='';props.work.notify?.('经验已删除。');await refresh();}}
  finally{deleting.value='';}
}
function sourceTitle(row){return row.source_session===props.work.s.session?runs.value.find(run=>run.id===row.source_run)?.title:null;}
async function inspectSource(row){
  if(sourceDetails.value[row.id]){delete sourceDetails.value[row.id];return;}
  const session=props.work.s.session;sourceBusy.value=row.id;
  try{const events=row.source_session===session?props.work.s.events:(await api(`/api/sessions/${row.source_session}`)).events;
    if(!disposed&&session===props.work.s.session)sourceDetails.value[row.id]=completedTasks(events).find(run=>run.id===row.source_run)||{missing:true};
  }finally{if(sourceBusy.value===row.id)sourceBusy.value='';}
}
</script>
<template><div class="learning-panel" :class="{'library-view':view==='library','summary-view':view==='summary'}">
<section v-if="view!=='library'" class="solution-builder"><h3>按任务或总结方向生成方案</h3><label for="solution-task">选择任务<select id="solution-task" v-model="selected" aria-label="选择已完成任务" :title="selectedTask?.prompt||'选择已完成任务'" :disabled="busy"><option value="">选择任务，或填写方向总结当前会话</option><option value="__session__">整个当前会话的已完成任务</option><option v-for="run in runs" :key="run.id" :value="run.id" :title="run.prompt||run.title">{{shortPrompt(run.prompt||run.title)}} · {{taskTime(run.time).replace(/:\d{2}$/,'')}}</option></select></label>
<p v-if="!runs.length" class="empty-state">还没有已结束的任务。先完成一个任务并验证结果，再来保存解决方法。</p>
<p v-if="sessionScope" class="section-note">总结范围：当前会话中 {{runs.length}} 个已完成任务。仅保存有真实工具证据支持的经验。</p><details v-else-if="selectedTask" class="source-preview"><summary>核对任务结果与证据</summary><TaskEvidence :task="selectedTask"/></details>
<label class="summary-focus">总结方向（选填）<textarea v-model="focus" :rows="view==='summary'?3:5" maxlength="2000" :disabled="busy" aria-label="经验总结方向" placeholder="例如：总结 Windows 路径与终端命令的问题及解决方法。"></textarea></label>
<label class="success-confirm"><input v-model="confirmed" type="checkbox" :disabled="!canExtract||busy" aria-label="确认任务成功">我已核对所选范围的结果，确认相关任务实现了目标</label>
<button class="secondary" :disabled="busy||work.s.running||(!selected&&!focus.trim())||!confirmed||!canExtract" @click="work.safe(extract)">{{submitting?'正在提交…':busy?'正在后台整理…':'生成可复用方案'}}</button><p v-if="extractError" class="extraction-error" role="alert">{{extractError}}</p><small>后台自动总结并保存，可刷新或切换页面；每次最多 3 条。</small></section>
<details v-if="visibleJobs.length" class="learning-jobs" aria-label="后台经验总结" :open="view!=='library'"><summary>{{view==='library'?'总结记录':'总结状态'}}</summary><div v-for="job in visibleJobs.slice(0,view==='library'?30:view==='summary'?1:3)" :key="job.id" class="learning-job"><strong>{{jobLabels[job.status]||job.status}} · {{shortPrompt(job.title)}}</strong><p v-if="job.focus">总结方向：{{shortPrompt(job.focus,40)}}</p><p v-if="['queued','running'].includes(job.status)">任务已交给后台，离开页面不影响保存。</p><p v-else-if="job.status==='completed'">{{job.result_count?`已保存或更新 ${job.result_count} 条经验，可在下方查看。`:'本次没有提炼出可复用经验。'}}</p><p v-else class="extraction-error" role="alert">{{job.error||'请核对后重新生成。'}}</p></div></details>
<div v-if="view==='summary'" class="summary-library-link"><button class="secondary" @click="work.s.page='experiences'">打开经验管理</button></div>
<template v-if="view!=='summary'"><div class="solution-library-heading"><h3>已保存的解决方案</h3><button class="quiet" @click="work.safe(refresh)">刷新</button></div>
<div v-if="view==='library'" class="experience-filters"><input v-model="query" type="search" aria-label="搜索经验" placeholder="搜索标题、适用场景或解决方法"><select v-model="enabledFilter" aria-label="筛选经验状态"><option value="all">全部状态</option><option value="enabled">已启用</option><option value="disabled">已停用</option></select><span>{{filteredRows.length}} / {{rows.length}} 条</span></div>
<p v-if="!rows.length" class="empty-state">暂无经验。可回到工作台，在右侧总结任务经验。</p><p v-else-if="!filteredRows.length" class="empty-state">没有符合条件的经验，请调整搜索或筛选。</p><div class="solution-list">
<article v-if="view==='library'" v-for="row in filteredRows" :key="row.id" class="solution-card" :class="{'is-disabled':!row.enabled}"><button type="button" class="solution-card-open" :aria-label="`查看经验：${row.title}`" @click="openDetail(row)"><div class="solution-title"><strong>{{row.title}}</strong><span>{{row.enabled?'已启用':'已停用'}}</span></div><p class="solution-summary">{{row.when}}</p><div class="solution-card-meta"><span>确认 {{row.confirmations}} 次 · {{row.evidence.length}} 条证据</span><span>查看详情</span></div></button></article><article v-if="view!=='library'" v-for="row in filteredRows" :key="row.id" class="solution-card" :class="{'is-disabled':!row.enabled}"><div class="solution-title"><strong>{{row.title}}</strong><span>{{row.enabled?'已启用':'已停用'}}</span></div><dl><dt>适用场景</dt><dd>{{row.when}}</dd><dt>解决方法与验证</dt><dd class="solution-strategy">{{row.strategy}}</dd></dl><p v-if="allSessions" class="solution-source">来源会话：{{row.source_session_title||work.s.sessions?.find(session=>session.id===row.source_session)?.title||'其他会话'}}</p><p class="solution-source">来源任务：{{sourceTitle(row)||'查看来源任务了解原始需求'}}<br>已确认 {{row.confirmations}} 次 · 引用 {{row.evidence.length}} 条工具证据</p><div class="solution-actions"><button class="quiet" :disabled="!!sourceBusy" @click="work.safe(()=>inspectSource(row))">{{sourceBusy===row.id?'正在读取…':sourceDetails[row.id]?'收起来源任务':'查看来源任务'}}</button><button class="quiet" @click="work.safe(()=>toggle(row))">{{row.enabled?'停用方案':'启用方案'}}</button><button v-if="deleteConfirm!==row.id" class="quiet delete-lesson" :disabled="!!deleting" @click="deleteConfirm=row.id">删除经验</button><template v-else><span class="delete-note">确定删除这条经验？</span><button class="quiet delete-lesson" :disabled="!!deleting" @click="work.safe(()=>remove(row))">{{deleting===row.id?'正在删除…':'确认删除'}}</button><button class="quiet" :disabled="!!deleting" @click="deleteConfirm=''">取消</button></template></div><template v-if="sourceDetails[row.id]"><p v-if="sourceDetails[row.id].missing" class="empty-state">原始任务记录已不可用。</p><TaskEvidence v-else :task="sourceDetails[row.id]"/></template></article></div></template><BaseDialog v-if="view==='library'&&detailRow" class="library-detail experience-detail" :open="!!detailRow" :busy="!!deleting" labelledby="experience-detail-title" @close="detailId='';deleteConfirm=''"><template v-if="detailRow"><header class="library-detail-heading"><div><span class="detail-kind">经验详情 · {{detailRow.enabled?'已启用':'已停用'}}</span><h2 id="experience-detail-title">{{detailRow.title}}</h2></div><button type="button" class="detail-close" aria-label="关闭经验详情" :disabled="!!deleting" @click="detailId='';deleteConfirm=''">×</button></header><div class="library-detail-content experience-detail-body"><dl><dt>适用场景</dt><dd>{{detailRow.when}}</dd><dt>解决方法与验证</dt><dd class="solution-strategy">{{detailRow.strategy}}</dd></dl><p v-if="allSessions" class="solution-source">来源会话：{{detailRow.source_session_title||work.s.sessions?.find(session=>session.id===detailRow.source_session)?.title||'其他会话'}}</p><p class="solution-source">来源任务：{{sourceTitle(detailRow)||'查看来源任务了解原始需求'}}<br>已确认 {{detailRow.confirmations}} 次 · 引用 {{detailRow.evidence.length}} 条工具证据</p><div class="solution-actions"><button class="quiet" :disabled="!!sourceBusy" @click="work.safe(()=>inspectSource(detailRow))">{{sourceBusy===detailRow.id?'正在读取…':sourceDetails[detailRow.id]?'收起来源任务':'查看来源任务'}}</button><button class="quiet" @click="work.safe(()=>toggle(detailRow))">{{detailRow.enabled?'停用方案':'启用方案'}}</button><button v-if="deleteConfirm!==detailRow.id" class="quiet delete-lesson" :disabled="!!deleting" @click="deleteConfirm=detailRow.id">删除经验</button><template v-else><span class="delete-note">确定删除这条经验？</span><button class="quiet delete-lesson" :disabled="!!deleting" @click="work.safe(()=>remove(detailRow))">{{deleting===detailRow.id?'正在删除…':'确认删除'}}</button><button class="quiet" :disabled="!!deleting" @click="deleteConfirm=''">取消</button></template></div><template v-if="sourceDetails[detailRow.id]"><p v-if="sourceDetails[detailRow.id].missing" class="empty-state">原始任务记录已不可用。</p><TaskEvidence v-else :task="sourceDetails[detailRow.id]"/></template></div></template></BaseDialog></div></template>
<style scoped>
.source-preview summary{cursor:pointer;font-size:12px;color:#5966b3}.source-preview .task-evidence{margin-top:12px}.summary-library-link{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:12px}.experience-filters{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.experience-filters input{flex:1;min-width:180px;padding:11px 12px;border:1px solid #d8dfec;border-radius:8px;font:inherit}.experience-filters select{width:auto}.experience-filters>span{font-size:12px;color:#667085}.library-view .solution-list{display:grid}.library-view .solution-card{border:1px solid #dce2ee;border-radius:12px;background:#fff}.library-view .solution-title strong{font-size:17px}.library-view .solution-card dt{font-size:12px}.library-view .solution-card dd{font-size:14px;line-height:1.8}.library-view .solution-card .solution-source{font-size:12px}.summary-focus{display:grid;gap:7px}.summary-focus textarea{min-height:140px;line-height:1.6;box-sizing:border-box;width:100%;padding:9px;border:1px solid #cfd6e5;border-radius:7px;resize:vertical;font:inherit;color:inherit;background:#fff}.learning-jobs>summary{cursor:pointer;font-size:13px;font-weight:600;color:#344054}.learning-jobs{border:1px solid #dce2f0;border-radius:8px;padding:12px}.learning-job{padding-top:10px;font-size:12px}.learning-job p{font-size:11px;color:#667085}.delete-lesson,.delete-note{color:#b42318}.delete-note{font-size:11px}.extraction-error{color:#b42318;background:#fff3f2;padding:10px;border-radius:7px;overflow-wrap:anywhere}.learning-panel{display:grid;gap:16px;font-size:13px;min-width:0}.learning-panel p{line-height:1.65;margin:8px 0}.learning-panel small,.solution-source{color:#667085}.solution-builder{border:1px solid #dce2f0;border-radius:10px;padding:14px;display:grid;gap:12px;background:#fff}.learning-panel h3{font-size:14px;margin:0;color:#344054}.solution-builder>label:first-of-type{display:grid;gap:7px}.learning-panel select{box-sizing:border-box;width:100%;min-width:0;max-width:100%;padding:10px;border:1px solid #cfd6e5;border-radius:7px;background:#fff;color:inherit;text-overflow:ellipsis;font:inherit}.success-confirm{display:flex;gap:7px;align-items:flex-start;line-height:1.6}.success-confirm input{margin-top:4px;flex-shrink:0}.learning-panel small{font-size:11px;line-height:1.6}.solution-library-heading,.solution-title,.solution-actions{display:flex;justify-content:space-between;align-items:center;gap:10px}.solution-title{align-items:flex-start}.solution-title strong{font-size:14px;line-height:1.6}.solution-title span{white-space:nowrap;font-size:11px;color:#487c65;background:#edf6f1;padding:3px 6px;border-radius:4px}.solution-card{border-top:1px solid #dde3ee;padding-top:16px;overflow-wrap:anywhere}.solution-card.is-disabled .solution-title span{background:#f2f4f7;color:#667085}.solution-card dl{margin:12px 0}.solution-card dt{font-size:11px;font-weight:600;color:#667085;margin-top:12px}.solution-card dd{margin:5px 0 0;line-height:1.75}.solution-strategy{white-space:pre-wrap}.solution-source{font-size:11px}.solution-actions{justify-content:flex-start;flex-wrap:wrap;margin:8px 0}.solution-builder .secondary{width:100%}.learning-panel select:focus-visible{outline:2px solid #6571dd;outline-offset:2px}
.summary-view{gap:10px}.summary-view .solution-builder{padding:10px;gap:8px}.summary-view .summary-focus{gap:5px}.summary-view .summary-focus textarea{min-height:84px;height:84px;padding:8px;line-height:1.5}.summary-view .section-note{margin:0;font-size:11px;line-height:1.5}.summary-view p{margin:4px 0}.summary-view .success-confirm{line-height:1.4}.summary-view .learning-jobs{padding:9px}.summary-view .learning-job{padding-top:6px}.summary-view .solution-builder>label:first-of-type{gap:5px}
.library-view .solution-list{grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;align-items:stretch}.library-view .solution-card{padding:0;overflow:hidden}.solution-card-open{display:flex;flex-direction:column;gap:12px;width:100%;height:100%;min-height:160px;padding:18px;border:0;background:#fff;text-align:left;color:inherit;font:inherit;cursor:pointer}.solution-card-open:hover{background:#fafbff}.solution-card-open:focus-visible{outline:2px solid #6571dd;outline-offset:-3px}.library-view .solution-card-open .solution-title strong{font-size:15px;line-height:1.5;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.library-view .solution-summary{margin:0;font-size:12px;line-height:1.6;color:#667085;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.solution-card-meta{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:11px;color:#7d8ba5;margin-top:auto}.solution-card-meta>span:last-child{color:#6571c9;white-space:nowrap}.experience-detail-body dl{margin:0}.experience-detail-body dt{font-size:12px;font-weight:600;color:#667085;margin:16px 0 7px}.experience-detail-body dt:first-child{margin-top:0}.experience-detail-body dd{margin:0;font-size:14px;line-height:1.85;overflow-wrap:anywhere}.experience-detail-body .solution-source{font-size:12px;line-height:1.7}.experience-detail-body .solution-actions{margin:18px 0;gap:14px}.experience-detail-body .task-evidence{border-top:1px solid #e5e9f2;padding-top:14px}
@media(max-width:1200px){.library-view .solution-list{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:950px){.library-view .solution-list{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.library-view .solution-list{grid-template-columns:1fr}}
</style>
